React.useEffect(()=>{load()},[]); const statusLabel={draft:'草稿',pending:'待处理',in_progress:'进行中',approved:'已通过',completed:'已完成',rejected:'已驳回',inactive:'已停用'},tabStatus={草稿:'draft',待审批:'pending',审批中:'in_progress',进行中:'in_progress',已通过:'approved',已完成:'completed',已结束:'completed',已驳回:'rejected',未通过:'rejected',停用:'inactive'},allTabs=new Set(['全部','全部员工','全部文档','全部制度','全部流程']),activeTab=DEF.tabs[tab]||'';
