function openCreate(){setDialog({title:'',code:DEF.key.toUpperCase().replaceAll('_','-')+'-'+Date.now().toString().slice(-6),category:tabStatus[activeTab]||allTabs.has(activeTab)?'':activeTab,status:tabStatus[activeTab]||'draft',priority:'normal',owner_name:'',department:'',start_on:new Date().toISOString().slice(0,10),end_on:'',amount:'',quantity:'',details:'',source_ref:'',remarks:'',error:''})}
async function save(){if(!dialog?.title.trim())return setDialog(d=>({...d,error:'请填写标题后再保存'}));if(dialog.end_on&&dialog.start_on&&dialog.end_on<dialog.start_on)return setDialog(d=>({...d,error:'结束日期不能早于开始日期'}));setBusy(true);try{await request('/data/forge_administration_record',{method:'POST',body:JSON.stringify({title:dialog.title.trim(),code:dialog.code.trim()||null,page_key:DEF.key,category:dialog.category.trim()||null,status:dialog.status,priority:dialog.priority,owner_name:dialog.owner_name.trim()||null,department:dialog.department.trim()||null,start_on:dialog.start_on||null,end_on:dialog.end_on||null,amount:dialog.amount===''?null:Number(dialog.amount),quantity:dialog.quantity===''?null:Number(dialog.quantity),details:dialog.details.trim()||null,source_ref:dialog.source_ref.trim()||null,remarks:dialog.remarks.trim()||null})});setDialog(null);setToast(DEF.label+'记录已保存');await load()}catch(e){setDialog(d=>({...d,error:String(e.message||e)}))}finally{setBusy(false)}}
